import{_ as a,a as t,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const b=JSON.parse('{"title":"第二册：实践与进步 · Lesson 6 Percy Buttons","description":"学习 冠词与可数性，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 6 Percy Buttons","description":"学习 冠词与可数性，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 冠词与可数性，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 5 No wrong numbers","link":"/life/english/new-concept/book-2/unit-01/lesson-005"},"next":{"text":"第二册：实践与进步 · Lesson 7 Too late","link":"/life/english/new-concept/book-2/unit-01/lesson-007"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 5 No wrong numbers","link":"/life/english/new-concept/book-2/unit-01/lesson-005"},"next":{"text":"第二册：实践与进步 · Lesson 7 Too late","link":"/life/english/new-concept/book-2/unit-01/lesson-007"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-01/lesson-006.md","filePath":"life/english/new-concept/book-2/unit-01/lesson-006.md"}'),r={name:"life/english/new-concept/book-2/unit-01/lesson-006.md"};function i(l,e,s,h,d,c){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第二册-实践与进步-·-lesson-6-percy-buttons" tabindex="-1">第二册：实践与进步 · Lesson 6 Percy Buttons <a class="header-anchor" href="#第二册-实践与进步-·-lesson-6-percy-buttons" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 6 Percy Buttons&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-01/overview">单元 1</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>社区里有人用小小的帮助换来一顿热饭；练习第一次引入人物和再次提到人物时的冠词。本课的语言观察是：先说 a neighbour 引入一位未确定的邻居，再说 the neighbour 指回同一人；bread 通常不可数，数量应通过 a slice of 表达。完成学习后，请描述一次邻里互助，首次和再次提及同一人物时分别使用 a 与 the。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>bread</td><td>/bred/</td><td>n.</td><td>面包</td><td>a slice of bread</td></tr><tr><td>meal</td><td>/miːl/</td><td>n.</td><td>一餐</td><td>a warm meal</td></tr><tr><td>neighbour</td><td>/ˈneɪbə/</td><td>n.</td><td>邻居</td><td>a friendly neighbour</td></tr><tr><td>kind</td><td>/kaɪnd/</td><td>adj.</td><td>友善的</td><td>a kind gesture</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>a slice of bread — 一片面包，用 slice 计数</li><li>in return for — 作为对……的回报，for 后接所交换的帮助或物品</li></ul><h2 id="语法讲解-冠词与可数性" tabindex="-1">语法讲解：冠词与可数性 <a class="header-anchor" href="#语法讲解-冠词与可数性" aria-label="Permalink to &quot;语法讲解：冠词与可数性&quot;">​</a></h2><p>a/an 引入一个尚未特指的可数单数名词，an 的选择取决于后面词的开头读音；the 用于听者能确定的对象或特定范围。泛指复数和不可数名词时常不用冠词。可数性也会随词义变化，如 coffee 可指饮料，也可指一杯饮料。不要把每个汉语名词都配上 a；先判断本句中的词义、数量及听者能否辨认对象。本课应用：先说 a neighbour 引入一位未确定的邻居，再说 the neighbour 指回同一人；bread 通常不可数，数量应通过 a slice of 表达。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>A neighbour brought me some bread after the storm.</p></blockquote><p>暴风雨后，一位邻居给我送来了一些面包。</p><p>A neighbour 首次引入人物；some bread 是不可数名词短语；brought 带 me 与 some bread 两个宾语。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>a bread 通常不能表示“一片面包”；用 a slice of bread，特定面包种类的用法另论。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读 a neighbour 与 the neighbour，重读 neighbour，冠词用自然弱读。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>A neighbour brought me some bread after the storm. The neighbour had helped us clear the path. We invited her to share a warm meal.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>描述一次邻里互助，首次和再次提及同一人物时分别使用 a 与 the。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：A neighbour 首次引入人物；some bread 是不可数名词短语；brought 带 me 与 some bread 两个宾语。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：a bread 通常不能表示“一片面包”；用 a slice of bread，特定面包种类的用法另论。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>选择 a/some：A neighbour brought me ___ bread.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> some</p><p><strong>解析：</strong> 这里 bread 指食物材料，不按单个计数。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>是谁帮助清理了小路？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The neighbour did.</p><p><strong>解析：</strong> the neighbour 指回第一句中引入的人。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>把“两片面包”译成英语。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> two slices of bread</p><p><strong>解析：</strong> 数量由可数的 slices 表达，bread 不加 -s。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：冠词与可数性。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-005">上一课</a> · <a href="/life/english/new-concept/book-2/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-01/lesson-007">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const p=a(r,[["render",i]]);export{b as __pageData,p as default};
